/**
 * Stylesheet imports resolve to the raw CSS text, not to a side effect:
 * esbuild inlines them with `--loader:.css=text`, Vite resolves `?inline` to the
 * stylesheet text, and Vitest returns the content through `test.css: true`.
 */

declare module '*.css?inline' {
  const css: string;
  export default css;
}

declare module '*.css' {
  const css: string;
  export default css;
}

/* Hooks: --an-field-gap | --an-field-label-font-size | --an-field-hint-color
   | --an-field-error-color. Colours and scales come from @an-ui-kit/tokens, each
   with a literal fallback. */

:host {
  display: block;
  color-scheme: light dark;
}

:host([data-theme='dark']) {
  color-scheme: dark;
}

:host([data-theme='light']) {
  color-scheme: light;
}

.base {
  display: flex;
  flex-direction: column;
  gap: var(--an-field-gap, var(--an-space-2, 0.5rem));
  font-family: inherit;
  color: var(--an-color-fg-1, #18181b);
}

.label {
  display: inline-flex;
  align-items: baseline;
  gap: 0.25rem;
  color: var(--an-color-fg-1, #18181b);
  font-size: var(--an-field-label-font-size, var(--an-font-size-sm, 0.875rem));
  font-weight: 500;
  line-height: 1.4;
}

.required {
  color: var(--an-color-danger-9, #dc2626);
  font-weight: 600;
}

.control {
  display: block;
  min-width: 0;
}

.hint,
.error {
  margin: 0;
  font-size: var(--an-font-size-xs, 0.75rem);
  line-height: 1.4;
}

/* Weakened `--an-color-fg-1`: mixing against `transparent` keeps the hint
   legible in both colour schemes instead of pinning one palette step. */
.hint {
  color: var(--an-field-hint-color, color-mix(in oklab, var(--an-color-fg-1, #18181b) 62%, transparent));
}

.error {
  color: var(--an-field-error-color, var(--an-color-danger-9, #dc2626));
}

/* Author-origin `display` above would beat the UA `[hidden]` rule, so the
   empty label and the hidden hint/error need it spelled out here. */
[hidden] {
  display: none !important;
}

/* Guards against page-level preflight (e.g. Tailwind v4) leaking into the host. */
:host {
  box-sizing: border-box;
  border: 0 solid;
  margin: 0;
  line-height: 1.5;
}

import resetStyles from './reset.css?inline';

/** Values allowed for attribute-backed properties. */
export type Primitive = string | number | boolean;

/** Defaults for attribute-backed properties; keys define the public API. */
export type Defaults = Record<string, Primitive>;

/** `my-attr` -> `myAttr`, so an attribute can drive the camelCase property. */
function toCamelCase(name: string): string {
  return name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase());
}

/** `myAttr` -> `my-attr`, so a property can reflect to the attribute. */
function toKebabCase(name: string): string {
  return name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
}

/**
 * Dependency-free base class for every `an-*` custom element.
 *
 * Contract:
 * - Constructor only touches `this` (`attachShadow`, `attachInternals`, local
 *   fields, accessors): it never reads `document`, `window`, storage or the
 *   network, so importing a component stays safe under SSR and inside workers.
 * - `static defaults` declares the attribute-backed API. Property accessors are
 *   generated from it and reflect back to attributes, so `el.variant` and
 *   `variant="primary"` can never disagree; attributes stay the source of truth.
 * - Markup comes from `render()` as an HTML string and is written straight into
 *   the shadow root, including `static styles` plus the shared reset.
 * - Listeners belong on the shadow root (event delegation), because re-rendering
 *   replaces the inner markup.
 * - Every write re-renders before it returns, so `el.disabled = true` followed by
 *   a synchronous `shadowRoot` read already sees the new markup.
 * - Form participation is opt-in: a subclass sets `static formAssociated = true`
 *   and then gets `this.internals`, the platform lifecycle callbacks
 *   (`formAssociatedCallback`, `formResetCallback`, `formDisabledCallback`) and
 *   the protected `onFormReset` / `onFormDisabled` hooks.
 */
export abstract class AnElement extends HTMLElement {
  /** Shadow-DOM stylesheet source for this element. */
  static styles: string = '';

  /** Attribute-backed properties and their defaults. */
  static defaults: Defaults = {};

  /** Attributes the browser reports to `attributeChangedCallback`. */
  static get observedAttributes(): string[] {
    return Object.keys(this.defaults).map(toKebabCase);
  }

  /**
   * Opts the element into `ElementInternals` form participation.
   * Subclasses that submit/reset/validate through a form set this to `true`.
   */
  static formAssociated: boolean = false;

  /**
   * Platform form internals, attached only when `static formAssociated` is
   * `true`. `null` on elements that did not opt in and on DOM implementations
   * without `attachInternals()`.
   */
  protected internals: ElementInternals | null = null;

  #defaults: Defaults = {};
  #values: Record<string, Primitive> = {};
  #rendered = false;
  #reflecting = false;
  #fallbackStyle: HTMLStyleElement | null = null;

  constructor() {
    super();
    const ctor = this.constructor as typeof AnElement;
    const root = this.attachShadow({ mode: 'open' });

    if (ctor.formAssociated) {
      try {
        this.internals = this.attachInternals();
      } catch {
        // `attachInternals()` throws unless the element opted in, and some DOM
        // implementations (e.g. happy-dom) do not expose it at all: degrade to a
        // plain element instead of failing construction.
        this.internals = null;
      }
    }

    this.#defaults = ctor.defaults;
    this.#values = { ...ctor.defaults };
    this.#adoptStyles(root, `${resetStyles}\n${ctor.styles}`);

    for (const [key, fallback] of Object.entries(ctor.defaults)) {
      const type = typeof fallback;
      Object.defineProperty(this, key, {
        configurable: true,
        enumerable: true,
        get: () => this.#values[key],
        set: (next: Primitive) => this.#assign(key, next, type),
      });
    }
  }

  connectedCallback(): void {
    if (!this.#rendered) {
      this.#rendered = true;
      this.requestUpdate();
    }
    this.onConnect();
  }

  /** Re-renders the shadow root from `render()`. */
  requestUpdate(): void {
    const root = this.shadowRoot;
    if (!root || !this.#rendered) return;
    root.innerHTML = this.render();
    if (this.#fallbackStyle && !this.#fallbackStyle.isConnected) root.prepend(this.#fallbackStyle);
    this.afterRender();
  }

  disconnectedCallback(): void {
    this.onDisconnect();
  }

  /**
   * Platform callback: the element was associated with, or disassociated from,
   * a form. Association itself is opt-in, so the default implementation is a
   * no-op; a subclass may read `this.internals?.form` here.
   */
  formAssociatedCallback(): void {}

  /** Platform callback: the owning form was reset. */
  formResetCallback(): void {
    this.onFormReset();
  }

  /** Platform callback: the platform disabled or enabled the element. */
  formDisabledCallback(disabled: boolean): void {
    this.onFormDisabled(disabled);
  }

  /** Hook: connected and rendered; default no-op. */
  protected onConnect(): void {}

  /** Hook: disconnected from the document; default no-op. */
  protected onDisconnect(): void {}

  /** Hook: the owning form was reset; restore state here. Default no-op. */
  protected onFormReset(): void {}

  /** Hook: the platform-level disabled state changed; default no-op. */
  protected onFormDisabled(disabled: boolean): void {}

  /** Returns the shadow-DOM markup; called on connect and after every change. */
  protected abstract render(): string;

  /** Hook for state markup cannot express (e.g. `.disabled` on a child node). */
  protected afterRender(): void {}

  /** Dispatches a bubbling, composed `CustomEvent`. */
  emit<T>(name: string, detail?: T): boolean {
    return this.dispatchEvent(new CustomEvent<T>(name, { bubbles: true, composed: true, detail }));
  }

  attributeChangedCallback(name: string, oldValue: string | null, value: string | null): void {
    if (oldValue === value) return;
    const key = toCamelCase(name);
    if (!(key in this.#defaults)) return;
    this.#values[key] = this.#coerce(key, value); // attribute -> camelCase property
    if (this.#rendered && !this.#reflecting) this.requestUpdate();
  }

  #assign(key: string, next: Primitive, type: string): void {
    const value = type === 'boolean' ? Boolean(next) : type === 'number' ? Number(next) : String(next);
    if (Object.is(this.#values[key], value)) return;
    this.#values[key] = value;
    this.#reflect(key, value);
  }

  #reflect(key: string, value: Primitive): void {
    const attribute = toKebabCase(key);
    this.#reflecting = true;
    try {
      if (typeof value === 'boolean') this.toggleAttribute(attribute, value);
      else if (value === this.#defaults[key]) this.removeAttribute(attribute);
      else this.setAttribute(attribute, String(value));
    } finally {
      this.#reflecting = false;
    }
    if (this.#rendered) this.requestUpdate();
  }

  #coerce(key: string, value: string | null): Primitive {
    const fallback = this.#defaults[key];
    if (typeof fallback === 'boolean') return value !== null;
    if (value === null) return fallback;
    if (typeof fallback === 'number') return Number.isNaN(Number(value)) ? fallback : Number(value);
    return value;
  }

  #adoptStyles(root: ShadowRoot, text: string): void {
    if (!text.trim()) return;
    try {
      const sheet = new CSSStyleSheet();
      sheet.replaceSync(text);
      root.adoptedStyleSheets = [sheet];
    } catch {
      if (typeof document === 'undefined') return;
      const style = document.createElement('style');
      style.textContent = text;
      root.prepend(style);
      this.#fallbackStyle = style;
    }
  }
}

import fieldStyles from './an-field.css?inline';
import { AnElement } from '../internal/base';

/** Shown when a control reports `invalid` but carries no platform message. */
const FALLBACK_ERROR = '请输入有效值';

/**
 * Events a slotted control dispatches after its value changed. Any of them
 * clears the error text captured from an earlier `invalid` event.
 */
const CHANGE_EVENTS = [
  'input',
  'change',
  'an-input',
  'an-change',
  'an-checkbox-change',
  'an-switch-change',
  'an-radio-change',
  'an-select-change',
  'an-textarea-change',
] as const;

/** Classic `<p id="x">` counter, so every field gets stable, unique ids. */
let nextId = 0;

/** Escapes text used inside an attribute value or element content. */
function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (char) => `&#${char.charCodeAt(0)};`);
}

/** A slotted control that may expose the platform validation message. */
type ValidationTarget = EventTarget & { validationMessage?: string };

/**
 * Non-empty platform validation message carried by `target`.
 *
 * Every form-associated element in this package exposes `validationMessage` as a
 * getter (the host itself has none), and a native control carries the property
 * natively, so one read covers both; a target without the property yields `''`
 * and the caller falls back to its own text.
 */
function readValidationMessage(target: EventTarget | null | undefined): string {
  const message = (target as ValidationTarget | null | undefined)?.validationMessage;
  return typeof message === 'string' ? message.trim() : '';
}

/**
 * `<an-field>` — layout and error display for one form control.
 *
 * The element is deliberately **not** form-associated: `<an-input>`,
 * `<an-textarea>`, `<an-select>` and friends already participate in the native
 * `<form>`, so `requestSubmit()`, `FormData`, `reset()` and constraint
 * validation keep working without a wrapper. `<an-field>` only renders the
 * label/hint/error chrome, links them to the slotted control, and mirrors the
 * platform's own constraint message.
 *
 * Validation is never re-implemented here. The error text comes from the
 * `validationMessage` of whichever control dispatched `invalid`, caught during
 * the capture phase because `invalid` does not bubble. A non-empty `error`
 * attribute wins over that captured text.
 *
 * The host carries no observable attributes of its own beyond the four below;
 * `required` is presentational only (a star plus `aria-required`) and neither
 * marks the slotted control valid nor invalid.
 *
 * @attr label - Visible label text; the star follows it when `required` is set.
 * @attr hint - Secondary help text shown under the control.
 * @attr error - Forces the error message and wins over the captured one.
 * @attr required - Marks the field as required for presentation (`aria-required`).
 *
 * @slot - The control the field wraps; every direct element child is treated as one.
 *
 * @cssprop --an-field-gap - Space between label, control, hint and error; defaults to `--an-space-2` (0.5rem).
 * @cssprop --an-field-label-font-size - Label text size; defaults to `--an-font-size-sm` (0.875rem).
 * @cssprop --an-field-hint-color - Hint colour; defaults to `--an-color-fg-1` weakened to 62%.
 * @cssprop --an-field-error-color - Error colour; defaults to `--an-color-danger-9`.
 * @csspart base - Column wrapper around the label, control, hint and error.
 * @csspart label - The `<label>`; rendered empty and hidden when `label` is unset.
 * @csspart required - The `*` after the label text; rendered only when `required` is set.
 * @csspart control - Wrapper around the `<slot>`; carries `data-invalid` while an error shows.
 * @csspart hint - The `<p>` hint; hidden while `hint` is empty.
 * @csspart error - The `<p role="alert">` error; hidden while no error shows.
 */
export class AnField extends AnElement {
  static override styles: string = fieldStyles;

  static override defaults = {
    label: '',
    hint: '',
    error: '',
    required: false,
  };

  declare label: string;
  declare hint: string;
  declare error: string;
  declare required: boolean;

  /** Constraint message captured from a control's `invalid` event. */
  #autoError = '';
  /** Control that dispatched the `invalid` event, if any. */
  #invalidTarget: Element | null = null;
  /**
   * Attributes this element wrote onto a control, keyed by control. Cleanup and
   * the "the author already linked this" checks both read it, so a consumer's
   * own `aria-label` / `aria-describedby` is never removed or overwritten.
   */
  #written = new WeakMap<Element, Set<string>>();
  #labelId = `an-field-${++nextId}-label`;
  #hintId = `an-field-${nextId}-hint`;
  #errorId = `an-field-${nextId}-error`;

  constructor() {
    super();
    // `invalid` never bubbles; a capture listener on the host is the only way to
    // see it. It is not composed either, so an inner native input inside a
    // control's own shadow root stays out of this listener — exactly what we want.
    this.addEventListener('invalid', this.#onInvalid, true);
    for (const type of CHANGE_EVENTS) this.addEventListener(type, this.#onValueChange);
  }

  protected render(): string {
    const error = this.#displayError;
    const label =
      `<label class="label" part="label" id="${this.#labelId}"${this.label ? '' : ' hidden'}>` +
      escapeHtml(this.label) +
      (this.required ? '<span class="required" part="required" aria-hidden="true">*</span>' : '') +
      '</label>';
    const hint = `<p class="hint" part="hint" id="${this.#hintId}"${this.hint ? '' : ' hidden'}>${escapeHtml(this.hint)}</p>`;
    const errorText = `<p class="error" part="error" id="${this.#errorId}" role="alert"${error ? '' : ' hidden'}>${escapeHtml(error)}</p>`;
    const control = `<div class="control" part="control"${error ? ' data-invalid=""' : ''}><slot></slot></div>`;

    return `<div class="base" part="base">${label}${control}${hint}${errorText}</div>`;
  }

  protected override afterRender(): void {
    const slot = this.shadowRoot?.querySelector('slot');
    slot?.addEventListener('slotchange', this.#onSlotChange);
    this.#linkAll();
  }

  #onSlotChange = (): void => {
    this.#linkAll();
  };

  #linkAll(): void {
    for (const control of Array.from(this.children)) this.#link(control);
  }

  /**
   * Mirrors the label/hint/error text onto one slotted control.
   *
   * IDREFs cannot cross a shadow boundary, so `aria-labelledby` /
   * `aria-describedby` (which point at elements inside this shadow root) are
   * only the declarative half of the link: wherever that resolution is not
   * honoured, `aria-label` and `aria-description` carry the same text and keep
   * the control named and described. Author-provided values win over both.
   */
  #link(control: Element): void {
    const error = this.#displayError;
    const target = this.#invalidTarget;
    // A captured message belongs to one control; an `error` attribute describes
    // the whole field, so every control inherits it.
    const attached = target !== null && target.isConnected && this.contains(target);
    const invalid = error && (!attached || target === control) ? 'true' : null;
    const nameable =
      this.label !== '' &&
      !control.hasAttribute('label') &&
      this.#external(control, 'aria-label') === null &&
      this.#external(control, 'aria-labelledby') === null;
    const hasText = this.hint !== '' || error !== '';
    const ids = [this.hint ? this.#hintId : '', error ? this.#errorId : ''].filter(Boolean).join(' ');
    const text = [this.hint, error].filter(Boolean).join(' ');

    this.#write(control, 'aria-labelledby', nameable ? this.#labelId : null);
    this.#write(control, 'aria-label', nameable ? this.label : null);
    this.#write(control, 'aria-describedby', hasText && this.#external(control, 'aria-describedby') === null ? ids : null);
    this.#write(control, 'aria-description', hasText && this.#external(control, 'aria-description') === null ? text : null);
    this.#write(control, 'aria-required', this.required ? 'true' : null);
    this.#write(control, 'aria-invalid', invalid);
  }

  /** Current attribute value of `control`, ignoring values this field wrote. */
  #external(control: Element, name: string): string | null {
    return this.#written.get(control)?.has(name) ? null : control.getAttribute(name);
  }

  /** Sets or removes `name` on `control`, remembering ownership for cleanup. */
  #write(control: Element, name: string, value: string | null): void {
    const written = this.#written.get(control) ?? new Set<string>();

    if (value === null) {
      if (!written.delete(name)) return;
      this.#written.set(control, written);
      control.removeAttribute(name);
      return;
    }

    written.add(name);
    this.#written.set(control, written);
    if (control.getAttribute(name) !== value) control.setAttribute(name, value);
  }

  /** Error text actually shown: the attribute wins over the captured message. */
  get #displayError(): string {
    return this.error || this.#autoError;
  }

  #onInvalid = (event: Event): void => {
    if (!this.#owns(event.target)) return;

    const target = event.target as ValidationTarget;
    // The control reports the message through its own getter; an empty or absent
    // one falls back to the local text rather than showing nothing.
    const message = readValidationMessage(target) || FALLBACK_ERROR;
    const moved = this.#invalidTarget !== target;
    this.#invalidTarget = target as Element;

    if (this.#autoError !== message) this.#setAutoError(message);
    // Two controls can report the same text; `aria-invalid` still moves to the
    // control that reported last.
    else if (moved) this.requestUpdate();
  };

  #onValueChange = (event: Event): void => {
    if (!this.#owns(event.target)) return;
    this.#invalidTarget = null;
    this.#setAutoError('');
  };

  /**
   * Whether `target` is a control this field owns. A nested `<an-field>` owns
   * its own controls, so its events are not allowed to leak into this one.
   */
  #owns(target: EventTarget | null): target is Element {
    return target instanceof Element && this.contains(target) && target.closest('an-field') === this;
  }

  #setAutoError(message: string): void {
    if (this.#autoError === message) return;
    this.#autoError = message;
    this.requestUpdate();
  }
}
